const items = $input.all();
const returnData = [];

function escapeHtml(str) {
  if (str === null || str === undefined) return '';
  return String(str)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

for (const item of items) {
  const data = item.json.body || item.json;

  const rawTradeName = data.tradeName;
  const rawOwnerEmail = String(data.ownerEmail || '').trim();
  const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

  if (!rawOwnerEmail || !rawTradeName || !emailRegex.test(rawOwnerEmail)) {
    continue;
  }

  const tradeName = escapeHtml(rawTradeName);
  const ownerEmail = rawOwnerEmail;
  const ingredientName = escapeHtml(data.ingredient?.name || 'Insumo');
  const rawProducts = Array.isArray(data.criticalProducts) ? data.criticalProducts : [];

  const formatPercent = (n) => {
    return (Number(n) || 0).toLocaleString('es-AR', {
      minimumFractionDigits: 2,
      maximumFractionDigits: 2
    }) + '%';
  };

  const formatARS = (n) => {
    return new Intl.NumberFormat('es-AR', {
      style: 'currency',
      currency: 'ARS',
      minimumFractionDigits: 2,
      maximumFractionDigits: 2
    }).format(Number(n) || 0);
  };

  let productRowsHtml = '';
  let productRowsText = '';

  for (const prod of rawProducts) {
    const pName = escapeHtml(prod.productName || prod.name || 'Producto');
    const pCurrentMargin = escapeHtml(formatPercent(prod.currentMarginPercent || prod.newMarginPercent));
    const pMinMargin = escapeHtml(formatPercent(prod.minMarginPercent || prod.targetMarginPercent));
    const pCost = escapeHtml(formatARS(prod.newCost || prod.cost));

    const rawId = String(prod.productId || prod.id || '').replace(/[^a-zA-Z0-9_-]/g, '');
    const pLink = rawId ? `https://margenx.tech/productos/${rawId}` : 'https://margenx.tech/productos';

    productRowsHtml += `
      <tr style="border-bottom: 1px solid #e2e8f0;">
        <td style="padding: 12px 14px; font-size: 14px; font-weight: 600; color: #0f172a;">
          ${pName}
          <div style="font-size: 12px; font-weight: 400; color: #64748b;">Nuevo costo: ${pCost}</div>
        </td>
        <td style="padding: 12px 14px; font-size: 13px; font-weight: 700; color: #dc2626; text-align: right;">
          <span style="background-color: #fee2e2; color: #b91c1c; padding: 3px 8px; border-radius: 4px; border: 1px solid #fecaca; display: inline-block;">
            ${pCurrentMargin}
          </span>
        </td>
        <td style="padding: 12px 14px; font-size: 13px; color: #334155; text-align: right; font-weight: 600;">${pMinMargin}</td>
        <td style="padding: 12px 14px; text-align: center;">
          <a href="${pLink}" target="_blank" style="background-color: #4f46e5; color: #ffffff; padding: 6px 12px; font-size: 12px; font-weight: 600; text-decoration: none; border-radius: 4px; display: inline-block;">
            Ajustar
          </a>
        </td>
      </tr>
    `;

    productRowsText += `* ${pName}:\n  - Margen Actual: ${pCurrentMargin} (Mínimo requerido: ${pMinMargin})\n  - Enlace de ajuste: ${pLink}\n\n`;
  }

  const rawPrimaryId = String(rawProducts[0]?.productId || rawProducts[0]?.id || '').replace(/[^a-zA-Z0-9_-]/g, '');
  const primaryCtaUrl = rawPrimaryId
    ? `https://margenx.tech/productos/${rawPrimaryId}`
    : 'https://margenx.tech/productos';

  const safeTradeNameSubject = rawTradeName.replace(/[\r\n]/g, '').trim();
  const emailSubject = `[MargenX ALERTA] Producto con margen bajo detectado - ${safeTradeNameSubject}`;

  const emailHtml = `<!DOCTYPE html>
<html lang="es">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Alerta de Margen Crítico</title>
</head>
<body style="margin: 0; padding: 0; background-color: #f8fafc; font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif; color: #0f172a;">
  <table width="100%" cellpadding="0" cellspacing="0" border="0" style="background-color: #f8fafc; padding: 24px 12px;">
    <tr>
      <td align="center">
        <table width="100%" cellpadding="0" cellspacing="0" border="0" style="max-width: 600px; background-color: #ffffff; border-radius: 12px; overflow: hidden; border: 1px solid #e2e8f0; box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.05);">
          <tr>
            <td style="background-color: #0f172a; padding: 20px 24px; text-align: left;">
              <table width="100%" cellpadding="0" cellspacing="0" border="0">
                <tr>
                  <td>
                    <span style="font-size: 20px; font-weight: 800; color: #ffffff; letter-spacing: 0.5px;">MARGEN<span style="color: #6366f1;">X</span></span>
                    <span style="font-size: 11px; color: #94a3b8; display: block; margin-top: 2px; text-transform: uppercase; letter-spacing: 1px;">Control de Rentabilidad en Tiempo Real</span>
                  </td>
                  <td align="right">
                    <span style="background-color: #450a0a; color: #fca5a5; font-size: 11px; font-weight: 700; padding: 4px 10px; border-radius: 9999px; border: 1px solid #7f1d1d; text-transform: uppercase;">Alerta Crítica</span>
                  </td>
                </tr>
              </table>
            </td>
          </tr>
          <tr>
            <td style="padding: 24px 24px 16px 24px;">
              <div style="background-color: #fef2f2; border-left: 4px solid #ef4444; padding: 14px 16px; border-radius: 0 8px 8px 0;">
                <p style="margin: 0; font-size: 14px; font-weight: 700; color: #991b1b;">
                  Atención: Insumo con impacto directo en margen
                </p>
                <p style="margin: 4px 0 0 0; font-size: 13px; color: #7f1d1d;">
                  Se detectaron productos de <strong>${tradeName}</strong> cuya rentabilidad cayó por debajo del mínimo tras el aumento de <strong>${ingredientName}</strong>.
                </p>
              </div>
            </td>
          </tr>
          <tr>
            <td style="padding: 0 24px 20px 24px;">
              <table width="100%" cellpadding="0" cellspacing="0" border="0" style="border-collapse: collapse; border: 1px solid #e2e8f0; border-radius: 8px; overflow: hidden; width: 100%;">
                <thead>
                  <tr style="background-color: #f1f5f9; text-align: left;">
                    <th style="padding: 10px 14px; font-size: 11px; font-weight: 700; color: #475569; text-transform: uppercase;">Producto</th>
                    <th style="padding: 10px 14px; font-size: 11px; font-weight: 700; color: #b91c1c; text-transform: uppercase; text-align: right;">Margen Actual</th>
                    <th style="padding: 10px 14px; font-size: 11px; font-weight: 700; color: #475569; text-transform: uppercase; text-align: right;">Mínimo</th>
                    <th style="padding: 10px 14px; font-size: 11px; font-weight: 700; color: #475569; text-transform: uppercase; text-align: center;">Acción</th>
                  </tr>
                </thead>
                <tbody>
                  ${productRowsHtml}
                </tbody>
              </table>
            </td>
          </tr>
          <tr>
            <td style="padding: 0 24px 28px 24px;" align="center">
              <a href="${primaryCtaUrl}" target="_blank" style="background-color: #4f46e5; color: #ffffff; padding: 14px 28px; font-size: 14px; font-weight: 700; text-decoration: none; border-radius: 6px; display: inline-block; text-align: center; box-shadow: 0 2px 4px rgba(79, 70, 229, 0.25);">
                Ir a Ajustar Precios en MargenX &rarr;
              </a>
            </td>
          </tr>
          <tr>
            <td style="background-color: #f8fafc; border-top: 1px solid #e2e8f0; padding: 20px 24px; text-align: center;">
              <p style="margin: 0; font-size: 12px; color: #64748b;">
                Comercio: <strong>${tradeName}</strong> | Destinatario: ${ownerEmail}
              </p>
              <p style="margin: 8px 0 0 0; font-size: 11px; color: #94a3b8;">
                MargenX SaaS &bull; UNaB 2026 &bull; Soporte: contacto@margenx.tech
              </p>
            </td>
          </tr>
        </table>
      </td>
    </tr>
  </table>
</body>
</html>`;

  const emailText = `[MargenX ALERTA] Producto con margen bajo detectado\nComercio: ${tradeName}\n\nATENCIÓN: Se detectaron productos con rentabilidad comprometida tras la modificación de ${ingredientName}.\n\n${productRowsText}Para ajustar precios inmediatamente:\n${primaryCtaUrl}\n\n---\nMargenX SaaS - Soporte: contacto@margenx.tech`;

  returnData.push({
    json: {
      tradeName,
      ownerEmail,
      emailSubject,
      emailHtml,
      emailText
    }
  });
}

return returnData;
